#!/usr/bin/env python3
"""Mix: HTTP server + markdown parser -> serves rendered markdown."""
import re, threading, urllib.request
from http.server import BaseHTTPRequestHandler, HTTPServer

DOC = "# JAH Docs\n\nWelcome to the **markdown** web server.\n\n- fast\n- simple\n- tested"

def md_to_html(md):
    html = []
    for line in md.split("\n"):
        s = line.rstrip()
        if s.startswith("# "): html.append("<h1>%s</h1>" % s[2:])
        elif s.startswith("- "): html.append("<li>%s</li>" % s[2:])
        elif s.strip(): html.append("<p>%s</p>" % s)
    h = "\n".join(html)
    return re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", h)

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        body = ("<html><body>" + md_to_html(DOC) + "</body></html>").encode()
        self.send_response(200)
        self.send_header("Content-Type", "text/html")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers(); self.wfile.write(body)
    def log_message(self, *a): pass

if __name__ == "__main__":
    srv = HTTPServer(("127.0.0.1", 0), Handler)
    port = srv.server_address[1]
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    with urllib.request.urlopen("http://127.0.0.1:%d/" % port, timeout=10) as r:
        body = r.read().decode()
    assert "<h1>JAH Docs</h1>" in body and "<b>markdown</b>" in body and "<li>fast</li>" in body
    srv.shutdown(); srv.server_close()
    print("OK: markdown rendered and served over HTTP")

#!/usr/bin/env python3
"""Mix: password generator + caesar cipher -> encrypted vault."""
import random, string

def make_password(length=14, rng=None):
    rng = rng or random.Random()
    alpha = string.ascii_letters + string.digits
    return "".join(rng.choice(alpha) for _ in range(length))

def caesar(text, shift):
    out = []
    for ch in text:
        if "a" <= ch <= "z": out.append(chr((ord(ch)-97+shift) % 26 + 97))
        elif "A" <= ch <= "Z": out.append(chr((ord(ch)-65+shift) % 26 + 65))
        else: out.append(ch)
    return "".join(out)

class Vault:
    def __init__(self, shift): self.shift, self.store = shift, {}
    def save(self, site, password): self.store[site] = caesar(password, self.shift)
    def load(self, site): return caesar(self.store[site], -self.shift)

if __name__ == "__main__":
    rng = random.Random(21)
    v = Vault(shift=7)
    pw = make_password(rng=rng)
    v.save("example.com", pw)
    print("stored (encrypted):", v.store["example.com"])
    assert v.load("example.com") == pw and v.store["example.com"] != pw
    print("OK: password vault encrypts at rest, decrypts on load")

#!/usr/bin/env python3
"""Mix: bubble sort + binary search -> sort/search pipeline."""
def bubble_sort(a):
    a = a[:]
    for i in range(len(a)):
        for j in range(len(a)-1-i):
            if a[j] > a[j+1]: a[j], a[j+1] = a[j+1], a[j]
    return a

def binary_search(a, t):
    lo, hi = 0, len(a)-1
    while lo <= hi:
        m = (lo+hi)//2
        if a[m] == t: return m
        lo, hi = (m+1, hi) if a[m] < t else (lo, m-1)
    return -1

if __name__ == "__main__":
    data = [9, 3, 7, 1, 8, 2, 6, 5, 4]
    s = bubble_sort(data)
    print("sorted:", s)
    for target in (1, 5, 9):
        idx = binary_search(s, target)
        print("search %d -> index %d" % (target, idx))
        assert s[idx] == target
    assert binary_search(s, 10) == -1
    print("OK: sort/search pipeline works")

#!/usr/bin/env python3
"""Mix: csv->json + pretty printer -> data format converter."""
import csv, json, io

def csv_to_json(text):
    return list(csv.DictReader(io.StringIO(text)))

def pretty(obj):
    return json.dumps(obj, indent=2, sort_keys=True)

if __name__ == "__main__":
    csv_text = "name,score\nAda,95\nGrace,100\n"
    data = csv_to_json(csv_text)
    out = pretty(data)
    print(out)
    back = json.loads(out)
    assert back[1]["name"] == "Grace" and back[0]["score"] == "95"
    print("OK: CSV -> JSON -> pretty print pipeline works")

