#!/usr/bin/env python3
"""Mix: fibonacci + prime sieve -> prime fibonacci numbers."""
def fibs(n):
    a, b, out = 0, 1, []
    for _ in range(n):
        out.append(a); a, b = b, a+b
    return out

def sieve(n):
    sp = [True]*(n+1); sp[0]=sp[1]=False
    for i in range(2, int(n**0.5)+1):
        if sp[i]:
            for j in range(i*i, n+1, i): sp[j]=False
    return set(i for i,p in enumerate(sp) if p)

if __name__ == "__main__":
    fs = fibs(25)
    primes = sieve(max(fs))
    pf = [f for f in fs if f in primes]
    print("prime fibs:", pf)
    assert pf == [2, 3, 5, 13, 89, 233, 1597, 28657]
    print("OK: 8 prime Fibonacci numbers found below fib(25)")

#!/usr/bin/env python3
"""Mix: base64 + url parser -> data URL builder/verifier."""
import base64
from urllib.parse import urlparse

def make_data_url(mime, text):
    return "data:%s;base64,%s" % (mime, base64.b64encode(text.encode()).decode())

def parse_data_url(url):
    p = urlparse(url)
    assert p.scheme == "data"
    mime, _, payload = p.path.partition(";base64,")
    return mime, base64.b64decode(payload).decode()

if __name__ == "__main__":
    url = make_data_url("text/plain", "Hello, JAH!")
    print(url)
    mime, text = parse_data_url(url)
    assert mime == "text/plain" and text == "Hello, JAH!"
    print("OK: data URL built and parsed back")

#!/usr/bin/env python3
"""Mix: calculator + unit converter -> engineering calculator."""
import ast, operator

OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
       ast.Div: operator.truediv, ast.Pow: operator.pow}
def calc(expr):
    def ev(n):
        if isinstance(n, ast.Expression): return ev(n.body)
        if isinstance(n, ast.Constant): return n.value
        if isinstance(n, ast.BinOp): return OPS[type(n.op)](ev(n.left), ev(n.right))
        if isinstance(n, ast.UnaryOp): return -ev(n.operand)
        raise ValueError("nope")
    return ev(ast.parse(expr, mode="eval"))

def c_to_f(c): return c*9/5+32
def km_to_mi(km): return km/1.609344

if __name__ == "__main__":
    expr_val = calc("(212-32)*5/9")          # F back to C via expression
    print("(212-32)*5/9 =", expr_val)
    assert abs(expr_val - 100) < 1e-9
    conv = c_to_f(calc("20+15"))             # expression, then convert
    print("c_to_f(20+15) =", conv)
    assert conv == 95.0
    print("10 km race =", km_to_mi(calc("5*2")), "miles")
    print("OK: expressions feed unit conversions")

