#!/usr/bin/env python3
"""Mix: sieve + binary search -> prime lookup service."""
def sieve(n):
    sp=[True]*(n+1); sp[0]=sp[1]=False
    for i in range(2,int(n**0.5)+1):
        if sp[i]:
            for j in range(i*i,n+1,i): sp[j]=False
    return [i for i,p in enumerate(sp) if p]

def bsearch(a,t):
    lo,hi=0,len(a)-1
    while lo<=hi:
        m=(lo+hi)//2
        if a[m]==t: return True
        lo,hi=(m+1,hi) if a[m]<t else (lo,m-1)
    return False

class PrimeDB:
    def __init__(self, n): self.primes = sieve(n)
    def is_prime(self, x): return bsearch(self.primes, x)

if __name__ == "__main__":
    db = PrimeDB(1000)
    assert db.is_prime(997) and not db.is_prime(998) and db.is_prime(2)
    print("997 prime:", db.is_prime(997), "| 998 prime:", db.is_prime(998))
    print("OK: prime lookup service answers correctly")

#!/usr/bin/env python3
"""Mix: caesar + base64 -> secure message packer."""
import base64

def caesar(t, s):
    return "".join(chr((ord(c)-97+s)%26+97) if "a"<=c<="z" else
                   chr((ord(c)-65+s)%26+65) if "A"<=c<="Z" else c for c in t)

def pack(msg, shift):
    return base64.b64encode(caesar(msg, shift).encode()).decode()

def unpack(blob, shift):
    return caesar(base64.b64decode(blob.encode()).decode(), -shift)

if __name__ == "__main__":
    msg = "Meet at dawn"
    blob = pack(msg, 5)
    print("packed:", blob)
    assert unpack(blob, 5) == msg and blob != msg
    print("OK: pack/unpack round-trip through both layers")

#!/usr/bin/env python3
"""Mix: password generator + palindrome check -> password audit."""
import random, string, re

def make_password(n, rng):
    alpha = string.ascii_letters + string.digits
    return "".join(rng.choice(alpha) for _ in range(n))

def is_palindrome(t):
    c = re.sub(r"[^a-z0-9]", "", t.lower())
    return c == c[::-1] and len(c) > 1

def audit(pw):
    return {"length_ok": len(pw) >= 12,
            "has_digit": any(c.isdigit() for c in pw),
            "not_palindrome": not is_palindrome(pw)}

if __name__ == "__main__":
    rng = random.Random(55)
    pw = make_password(14, rng)
    rep = audit(pw)
    print(pw, rep)
    assert all(rep.values())
    assert not audit("abccbaabccba")["not_palindrome"]
    print("OK: strong password passes audit; palindrome password flagged")

#!/usr/bin/env python3
"""Mix: calculator + fibonacci -> scripted math REPL."""
import ast, operator

OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
       ast.Div: operator.truediv, ast.Pow: operator.pow}
def calc(e):
    def ev(n):
        if isinstance(n, ast.Expression): return ev(n.body)
        if isinstance(n, ast.Constant): return n.value
        if isinstance(n, ast.BinOp): return OPS[type(n.op)](ev(n.left), ev(n.right))
        raise ValueError("nope")
    return ev(ast.parse(e, mode="eval"))

def fib(n):
    a, b = 0, 1
    for _ in range(n): a, b = b, a+b
    return a

COMMANDS = ["2+3*4", "fib 10", "2**8", "fib 20", "(1+2)*(3+4)"]

if __name__ == "__main__":
    for cmd in COMMANDS:
        if cmd.startswith("fib "):
            out = fib(int(cmd[4:]))
        else:
            out = calc(cmd)
        print(">>> %-12s %s" % (cmd, out))
    assert fib(10) == 55 and calc("2+3*4") == 14 and fib(20) == 6765
    print("OK: REPL handled expressions and fib queries")
